package main

import "testing"

func total(weights []int) int {
    sum := 0
    for _, weight := range weights {
        sum = sum + weight
    }
    return sum
}

func TestTotal(t *testing.T) {
    got := total([]int{12000, 8400})
    if got != 20400 {
        t.Errorf("сумма = %d, ожидалось %d", got, 20400)
    }
}

